#include <bits/stdc++.h>
using namespace std;

vector<long long> multiplyModulo(const vector<long long>& a, const vector<long long>& b, long long m) {
    int size = 1;
    while (size < (int)(a.size() + b.size() - 1)) size <<= 1;
    vector<double> A(size, 0), B(size, 0);
    for (int i = 0; i < (int)a.size(); i++) {
        long long x = ((a[i] % m) + m) % m;
        A[i] = (double)(x & 0x7FFF);
    }
    for (int i = 0; i < (int)b.size(); i++) {
        long long x = ((b[i] % m) + m) % m;
        B[i] = (double)(x & 0x7FFF);
    }

    auto fftTransform = [](vector<double>& a, bool invert) {
        int n = (int)a.size();
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j >= bit; bit >>= 1)
                j -= bit;
            j += bit;
            if (i < j) swap(a[i], a[j]);
        }
        for (int len = 2; len <= n; len <<= 1) {
            double angle = 2 * M_PI / len * (invert ? -1 : 1);
            double wlenCos = cos(angle);
            double wlenSin = sin(angle);
            for (int i = 0; i < n; i += len) {
                double wRe = 1, wIm = 0;
                for (int j = 0; j < len / 2; j++) {
                    int u = i + j;
                    int v = i + j + len / 2;
                    double uVal = a[u];
                    double vVal = a[v] * wRe - a[v] * wIm;
                    a[u] = uVal + vVal;
                    a[v] = uVal - vVal;
                    double nextWRe = wRe * wlenCos - wIm * wlenSin;
                    double nextWIm = wRe * wlenSin + wIm * wlenCos;
                    wRe = nextWRe;
                    wIm = nextWIm;
                }
            }
        }
        if (invert) {
            for (int i = 0; i < n; i++) {
                a[i] /= n;
            }
        }
    };

    fftTransform(A, false);
    fftTransform(B, false);
    for (int i = 0; i < size; i++) {
        A[i] = A[i] * B[i];
    }
    fftTransform(A, true);
    vector<long long> res(a.size() + b.size() - 1);
    for (int i = 0; i < (int)res.size(); i++) {
        long long val = (long long)round(A[i]);
        res[i] = val % m;
    }
    return res;
}

